INSERT INTO city (id, name, autonomous_community, province, description, heritage_date, latitude, longitude, main_image) VALUES
(1, 'Córdoba', 'Andalucía', 'Córdoba',
 'Córdoba es una ciudad de impresionante legado histórico que fue, durante siglos, la capital de al-Ándalus, el califato musulmán de Occidente. Su mezquita-catedral, una de las obras maestras de la arquitectura islámica, representa un singular encuentro entre las culturas musulmana y cristiana. Iniciada en el siglo VIII por el califa Abderramán I, la mezquita fue ampliada por otros califas y, tras la Reconquista, fue convertida en catedral, lo que le da un carácter único, combinando arcos de herradura de la época musulmana con una estructura cristiana posterior. El Alcázar de los Reyes Cristianos, el puente romano y el barrio judío, con su estrechas callejuelas y patios adornados con flores, completan el entramado histórico que convierte a Córdoba en una ciudad imprescindible para los amantes de la historia y la arquitectura. Córdoba también es conocida por su legado en el campo de la filosofía, siendo cuna de pensadores como Averroes.',
 '1984-12-17', 37.8882, -4.7794, 'https://services.meteored.com/img/article/cordoba-la-unica-ciudad-del-mundo-con-cuatro-bienes-patrimonio-de-la-humanidad-1699285940128_1280.jpg'),
(2, 'Toledo', 'Castilla-La Mancha', 'Toledo',
 'Toledo, también conocida como la "Ciudad de las Tres Culturas", se ha destacado por ser un crisol de las civilizaciones cristiana, judía y musulmana, que convivieron durante la Edad Media. Su impresionante casco antiguo, que conserva una estructura medieval casi intacta, es una de las principales razones de su reconocimiento como Patrimonio de la Humanidad. La Catedral de Toledo, con su grandiosa arquitectura gótica, alberga una increíble colección de arte religioso. Además, el Alcázar y la iglesia de Santo Tomé, donde se encuentra la famosa pintura de El Greco "El entierro del Conde de Orgaz", son solo algunos de los monumentos que hacen de Toledo un museo al aire libre. Esta ciudad también fue la sede de la corte de los Reyes Católicos, lo que la convierte en un referente en la historia política y cultural de España.',
 '1986-11-26', 39.8628, -4.0273, 'https://turismo.toledo.es/images/paginas/c51a8825358461362bdc1f055f4e2c4d.jpg'),
(3, 'Salamanca', 'Castilla y León', 'Salamanca',
 'Salamanca es famosa por su universidad, fundada en 1218, que la convierte en una de las más antiguas de Europa y un centro de conocimiento de gran relevancia en la Edad Media y el Renacimiento. La ciudad no solo destaca por su universidad, sino por su impresionante conjunto arquitectónico. La Plaza Mayor, uno de los lugares más emblemáticos, es un ejemplo perfecto del estilo barroco español. La Casa de las Conchas, la Catedral Vieja y la Catedral Nueva, con sus diversos estilos arquitectónicos, ofrecen una visión única de la evolución histórica de Salamanca. La Universidad de Salamanca es especialmente conocida por su fachada, que alberga una rana esculpida que se dice trae suerte a quien la encuentra. Además, la ciudad ha sido cuna de grandes literatos y pensadores, lo que le da un aura de ciudad intelectual y cultural de primer orden.​',
 '1988-12-06', 40.9701, -5.6635, 'https://img2.rtve.es/imagenes/ciudades-espanolas-patrimonio-humanidad-episodio-3-salamanca/1628926950774.jpg'),
(4, 'Ávila', 'Castilla y León', 'Ávila',
 'Ávila es una ciudad amurallada que conserva una de las murallas medievales mejor preservadas del mundo. Con 2,5 kilómetros de largo, 87 torreones y 9 puertas, esta muralla rodea el casco antiguo de la ciudad, un testimonio vivo de la Edad Media. Además de su muralla, Ávila cuenta con una impresionante catedral gótica, que originalmente fue concebida como fortaleza, y varios conventos e iglesias, destacando el Convento de Santa Teresa, donde nació la mística Santa Teresa de Jesús. La ciudad tiene un aire de fortaleza que la hace única y conserva una gran riqueza de arquitectura medieval, lo que atrae a historiadores y turistas por igual. El encanto de Ávila también radica en sus calles empedradas, sus plazas y sus edificios, que han permanecido casi inalterados durante siglos.',
 '1985-12-06', 40.6565, -4.6818, 'https://spaneasylearning.com/wp-content/uploads/2021/06/avila.jpg'),
(5, 'Santiago de Compostela', 'Galicia', 'A Coruña',
 'Santiago de Compostela es el destino final de uno de los caminos de peregrinación más importantes de la cristiandad: el Camino de Santiago. La ciudad es conocida por su imponente catedral, que alberga la tumba del Apóstol Santiago y que es un lugar de devoción y de culto. La catedral es una obra maestra del arte románico y barroco, famosa por su Pórtico de la Gloria y por el Botafumeiro, el enorme incensario que se balancea durante las misas solemnes. El casco antiguo de Santiago es un laberinto de calles empedradas que conservan una atmósfera medieval que ha perdurado durante siglos. Además de su patrimonio religioso, Santiago de Compostela es un centro cultural y académico gracias a su universidad, y la ciudad ofrece una excelente gastronomía, destacando sus mariscos y el famoso pulpo a la gallega.',
 '1985-12-06', 42.8782, -8.5448, 'https://toxotravel.gal/wp-content/uploads/2024/08/11-1024x576.png'),
(6, 'Segovia', 'Castilla y León', 'Segovia',
 'Segovia es famosa por su acueducto romano, una de las construcciones antiguas mejor conservadas del mundo. Este acueducto, que transportaba agua desde las montañas cercanas hasta la ciudad, es una obra impresionante de ingeniería romana, con más de 160 arcos. La ciudad también destaca por su imponente alcázar, una fortaleza medieval que inspiró el castillo de Disney, y por su catedral gótica, que se alza sobre la Plaza Mayor. Segovia conserva un casco antiguo lleno de calles y plazas medievales, y su gastronomía es conocida por platos como el cochinillo asado. La ciudad también es famosa por su vinculación a la literatura, ya que fue el hogar del autor Antonio Machado, y por su historia como residencia real.​​',
 '1985-12-06', 40.9481, -4.1184, 'https://segovia.es/sites/default/files/styles/slider_medium/public/Media/Images/2021-06/Figura%209.%20Alcazar%20y%20Catedral.jpg?itok=xPCFroec'),
(7, 'Cáceres', 'Extremadura', 'Cáceres',
 'Cáceres es una ciudad medieval que conserva un excepcional casco antiguo que ha cambiado poco desde la Edad Media. El centro histórico de Cáceres es una mezcla de arquitectura románica, gótica y renacentista, con palacios, iglesias y torres que datan de los siglos XII al XVII. La Plaza Mayor y la Plaza de Santa María son dos de los lugares más emblemáticos de la ciudad, mientras que el Palacio de los Golfines y la Torre de Bujaco son ejemplos de la arquitectura nobiliaria de la época. Cáceres también fue un importante centro de comercio durante la Edad Media y el Renacimiento, y su ciudad vieja es uno de los mejor conservados conjuntos urbanos de este período en España.',
 '1986-12-06', 39.4766, -6.3722, 'https://saposyprincesas.elmundo.es/assets/2019/03/casco-1.jpg'),
(8, 'Cuenca', 'Castilla-La Mancha', 'Cuenca',
 'Cuenca es famosa por sus "casas colgadas", que se asoman al vacío desde los acantilados que bordean el río Huécar. Estas casas, que parecen desafiar la gravedad, han convertido a Cuenca en un icono de la arquitectura española. La ciudad también es conocida por su catedral gótica y por su casco antiguo, que conserva la estructura medieval y la arquitectura de la época. Cuenca está rodeada por un paisaje natural espectacular, con formaciones rocosas únicas y paisajes de gran belleza. Además, Cuenca ha sido escenario de importantes eventos culturales, como el Festival Internacional de Teatro.',
 '1996-12-06', 40.0704, -2.1374, 'https://okdiario.com/coolthelifestyle/img/2021/12/04/sin-titulot-1.jpg'),
(9, 'San Cristóbal de La Laguna', 'Canarias', 'Santa Cruz de Tenerife',
 'San Cristóbal de La Laguna, en la isla de Tenerife, es un ejemplo sobresaliente de una ciudad colonial no amurallada, que se distingue por su planificación urbana y su rica historia. Fundada en el siglo XV, La Laguna fue la primera ciudad de la isla y se convirtió en la capital de Tenerife. Lo más impresionante de La Laguna es su trazado urbano, que sigue un modelo de ciudad europea medieval, con calles rectas y amplias, plazas abiertas y una red de edificios de gran valor histórico. En la ciudad, se encuentran muchos edificios de estilo colonial, como la Catedral de La Laguna y el Palacio de Nava. La Laguna también es conocida por ser un importante centro de educación y cultura, siendo sede de la Universidad de La Laguna, fundada en 1792, y por su vibrante vida cultural. La ciudad se ha mantenido como un importante centro administrativo y religioso de Tenerife.',
 '1999-12-02', 28.4874, -16.3159, 'https://img2.rtve.es/imagenes/ciudades-espanola-patrimonio-humanidad-episodio-5-laguna/1575233303113.jpg'),
(10, 'Ibiza', 'Islas Baleares', 'Islas Baleares',
 'Ibiza, una de las islas más conocidas del Mediterráneo, es famosa por su biodiversidad, su paisaje espectacular y su rica herencia cultural. Además de sus playas paradisíacas y su vida nocturna vibrante, Ibiza cuenta con una serie de sitios de gran importancia histórica y cultural, como las murallas de la ciudad de Ibiza, que datan del siglo XVI, y el Dalt Vila, su casco antiguo, declarado Patrimonio de la Humanidad. La isla ha sido habitada desde la época fenicia, y su influencia se extiende a lo largo de los siglos, con huellas de varias culturas, incluidos los romanos y los árabes. En Ibiza, la naturaleza y la cultura se entrelazan, ofreciendo una experiencia única que abarca desde su entorno natural, con sus reservas marinas, hasta sus impresionantes monumentos históricos.',
 '1999-12-02', 38.9088, 1.4320, 'https://daleunavueltaalmundo.com/wp-content/uploads/2024/09/mirador-rei-jaume-i-ibiza.webp'),
(11, 'Úbeda', 'Andalucía', 'Jaén',
 'Úbeda es una joya del Renacimiento español, conocida por su bien conservado patrimonio arquitectónico. La ciudad fue un importante centro de poder durante el Renacimiento y, hoy en día, su casco histórico alberga una impresionante cantidad de palacios, iglesias y plazas de gran valor. Entre los monumentos más destacados se encuentra la iglesia de San Pablo, el Palacio Vela de los Cobos y la Plaza Vazquez de Molina. La influencia de arquitectos como Andrés de Vandelvira, que dejó una huella indeleble en la ciudad, es evidente en toda la arquitectura de Úbeda. Esta ciudad también está vinculada con la historia de la España moderna, ya que fue testigo de importantes eventos durante la Guerra de Independencia y la Revolución Industrial. Úbeda ha sido un centro cultural que conserva un aire tranquilo y monumental.',
 '2003-07-03', 38.0114, -3.3700, 'https://www.casascuevacazorla.com/wp-content/uploads/2017/08/MOnumentos-%C3%BCbeda-830x386.jpg'),
(12, 'Baeza', 'Andalucía', 'Jaén',
 'Junto con Úbeda, Baeza forma parte del Renacimiento andaluz, y su casco antiguo se encuentra maravillosamente conservado. Baeza es conocida por su Plaza del Pueblo, rodeada de palacetes, edificios renacentistas y su famosa Catedral, que combina elementos góticos y renacentistas. Baeza también fue un centro religioso y cultural de gran importancia, ya que en ella residieron figuras destacadas de la literatura y la religión española, como el poeta Antonio Machado. La ciudad también conserva sus antiguas murallas y muchas casas señoriales que reflejan la riqueza de la época. La tranquilidad y belleza de Baeza la hacen un lugar ideal para disfrutar del legado histórico y artístico del Renacimiento español.',
 '2003-07-03', 37.9937, -3.4710, 'https://viajes.nationalgeographic.com.es/medio/2024/10/28/baeza_ee3e5571_241028133128_1200x801.webp'),
(13, 'Alcalá de Henares', 'Comunidad de Madrid', 'Madrid',
 'Alcalá de Henares es una ciudad llena de historia, cultura y literatura. Su principal reclamo es ser la ciudad natal de uno de los más grandes escritores de la literatura universal: Miguel de Cervantes, autor de "Don Quijote de la Mancha". Alcalá es un centro cultural donde el legado de Cervantes está presente en cada rincón, y su Casa Natal, que se ha convertido en un importante lugar de peregrinación literaria, es uno de los monumentos más visitados. Además, la ciudad cuenta con una gran riqueza arquitectónica, destacando su universidad, que data de 1499, y su Plaza de Cervantes, que es un símbolo de su relación con la literatura española. Alcalá ha sido también un importante centro religioso y de educación a lo largo de los siglos.',
 '1998-12-02', 40.4818, -3.3640, 'https://fotografias.lasexta.com/clipping/cmsimages02/2023/11/16/38B86FCE-D374-4C45-B057-F8996AC0559E/imagen-alcala-henares_98.jpg?crop=2121,1193,x0,y196&width=1900&height=1069&optimize=high&format=webply'),
(14, 'Lugo', 'Galicia', 'Lugo',
 'Lugo es conocida por su impresionante muralla romana, que se encuentra completamente conservada y que rodea el casco antiguo de la ciudad. Esta muralla, que data del siglo III, es uno de los ejemplos más completos de arquitectura militar romana en todo el mundo. Lugo, además de su muralla, alberga una catedral de estilo románico y una gran cantidad de iglesias, lo que le otorga un carácter medieval muy marcado. La ciudad, situada en Galicia, también es famosa por su gastronomía, especialmente por los mariscos, y por sus paisajes naturales, como los que se encuentran en las riberas del río Miño. Lugo ha sido un importante punto de conexión en el noroeste de España, con una historia que abarca desde la época romana hasta la actualidad.',
 '2000-12-02', 43.0097, -7.5560, 'https://elviajeroaccidental.com/wp-content/uploads/2019/09/1-opt-vista-general-muralla-1024x768.jpg.webp'),
(15, 'Tarragona', 'Cataluña', 'Tarragona',
 'Tarragona es un sitio arqueológico de gran importancia debido a su herencia romana, que se refleja en monumentos como el anfiteatro romano, el acueducto, el foro y las murallas. Esta ciudad fue una de las capitales de la Hispania romana, y muchos de sus monumentos han llegado intactos o han sido cuidadosamente restaurados. El anfiteatro de Tarragona, situado junto al mar, es uno de los ejemplos más destacados de la arquitectura romana en España. La catedral de Tarragona, de estilo románico, y la Rambla Nova, que conecta el centro histórico con el mar, son también puntos de gran interés turístico. Tarragona también es famosa por su vibrante vida cultural, que incluye festivales como el Concurso de Castells, una tradición de construcción humana declarada Patrimonio Cultural Inmaterial de la Humanidad.',
 '2000-12-02', 41.1189, 1.2445, 'https://revistaiberica.com/wp-content/uploads/2019/10/aqueduct-3754932_640.jpg'),
(16, 'Elche', 'Comunidad Valenciana', 'Alicante',
 'Elche es conocida por su Palmeral, un espacio único y monumental que se considera uno de los más grandes y mejor conservados de Europa. Este Palmeral, declarado Patrimonio de la Humanidad, es una obra de ingeniería hidráulica que data de la época musulmana. Elche también es famosa por su historia ligada a las culturas ibérica, romana y musulmana. La Dama de Elche, una de las piezas más emblemáticas del arte ibérico, fue descubierta en la ciudad y es una de las esculturas más importantes de la antigüedad española. La Basílica de Santa María y el Museo Escolar de Puçol son otros ejemplos de su riqueza histórica y cultural. Elche es una ciudad donde la tradición y la modernidad conviven en perfecta armonía, siendo un centro económico y cultural clave en la provincia de Alicante.',
 '2000-12-02', 38.2699, -0.7126, 'https://revistaiberica.com/wp-content/uploads/2019/10/aqueduct-3754932_640.jpg');

